const LangCtx = createContext<{ lang: Lang; setLang: (l: Lang) => void; t: (k: string, params?: Record<string, unknown>) => string }>({
  lang: "en", setLang: () => {}, t: (k) => k,
});

// Apply before paint — no EN flash. Layout NEVER flips: the platform stays LTR
// in every language, only the text translates (Arabic glyphs render correctly
// inline via Unicode bidi — no dir=rtl, no mirrored layout, no shift).
const useIsoLayout = typeof window !== "undefined" ? useLayoutEffect : useEffect;

export function LangProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>("en");

  useIsoLayout(() => {
    const apply = (l: Lang) => {
      setLangState(l);
      document.documentElement.lang = l;
    };
    const saved = localStorage.getItem("lang") as Lang | null;
    if (saved && LANGS.some((l) => l.code === saved)) { apply(saved); return; }
    apply("en");
    // No stored choice → follow the admin-set platform default.
    fetch(`${process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000/api"}/config`)
      .then((r) => r.json())
      .then((c) => {
        const d = c.default_lang as Lang;
        if (d && LANGS.some((l) => l.code === d) && !localStorage.getItem("lang")) apply(d);
      })
      .catch(() => {});
  }, []);

  const setLang = (l: Lang) => {
    setLangState(l);
    localStorage.setItem("lang", l);
    document.documentElement.lang = l;
  };

  const t = (k: string, params?: Record<string, unknown>) => {
    let s: string = dict[k]?.[lang] ?? dict[k]?.en ?? k;
    if (params) for (const [pk, v] of Object.entries(params)) {
      const val = typeof v === "number" && /amount/i.test(pk)
        ? `$${v.toLocaleString("en-US", { maximumFractionDigits: 2 })}`
        : String(v);
      s = s.replaceAll(`{${pk}}`, val);
    }
    return s;
  };

  return <LangCtx.Provider value={{ lang, setLang, t }}>{children}</LangCtx.Provider>;
}

export const useT = () => useContext(LangCtx);
